assert.sameValue(
  result instanceof NonArray,
  false,
  'The result of evaluating (result instanceof NonArray) is expected to be false'
);
assert.compareArray(result, [obj, 4, 5, 6], 'The value of result is expected to be [obj, 4, 5, 6]');

