/*---
esid: sec-array.prototype.every
description: >
    Array.prototype.every - k values are passed in ascending numeric
    order
---*/

var arr = [0, 1, 2, 3, 4, 5];
var lastIdx = 0;
var called = 0;

function callbackfn(val, idx, o) {
  called++;
  if (lastIdx !== idx) {
    return false;
  } else {
    lastIdx++;
    return true;
  }
}

