/*---
esid: sec-array.prototype.indexof
description: >
    Array.prototype.indexOf uses inherited valueOf method when value
    of 'fromIndex' is an object with an own toString and inherited
    valueOf methods
---*/

var toStringAccessed = false;
var valueOfAccessed = false;

var proto = {
  valueOf: function() {
    valueOfAccessed = true;
    return 1;
  }
};

var Con = function() {};
Con.prototype = proto;

var child = new Con();
child.toString = function() {
  toStringAccessed = true;
  return 2;
};

assert.sameValue([0, true].indexOf(true, child), 1, '[0, true].indexOf(true, child)');
assert(valueOfAccessed, 'valueOfAccessed !== true');
assert.sameValue(toStringAccessed, false, 'toStringAccessed');

// ===== test/built-ins/Array/prototype/indexOf/15.4.4.14-5-26.js =====
// Copyright (c) 2012 Ecma International.  All rights reserved.
// This code is governed by the BSD license found in the LICENSE file.

/*---
esid: sec-array.prototype.indexof
description: >
    Array.prototype.indexOf - side effects produced by step 2 are
    visible when an exception occurs
---*/

var stepTwoOccurs = false;
var stepFiveOccurs = false;

var obj = {};

Object.defineProperty(obj, "length", {
  get: function() {
    stepTwoOccurs = true;
    if (stepFiveOccurs) {
      throw new Error("Step 5 occurred out of order");
    }
    return 20;
  },
  configurable: true
});

var fromIndex = {
  valueOf: function() {
    stepFiveOccurs = true;
    return 0;
  }
};

Array.prototype.indexOf.call(obj, undefined, fromIndex);

assert(stepTwoOccurs, 'stepTwoOccurs !== true');
assert(stepFiveOccurs, 'stepFiveOccurs !== true');

