/*---
description: Array.prototype.splice deletes length-start elements when called with one argument
info: |
  22.1.3.25 Array.prototype.splice (start, deleteCount , ...items )

  ...
  9. Else if the number of actual arguments is 1, then
    a. Let insertCount be 0.
    b. Let actualDeleteCount be len – actualStart.
esid: sec-array.prototype.splice
---*/

var array = ["first", "second", "third"];

var result = array.splice(1);

assert.sameValue(array.length, 1, "array length updated");
assert.sameValue(array[0], "first", "array[0] unchanged");

assert.sameValue(result.length, 2, "result array length correct");
assert.sameValue(result[0], "second", "result[0] correct");
assert.sameValue(result[1], "third", "result[1] correct");

// ===== test/built-ins/Array/prototype/splice/clamps-length-to-integer-limit.js =====
// Copyright (C) 2017 André Bargull. All rights reserved.
// This code is governed by the BSD license found in the LICENSE file.

/*---
esid: sec-array.prototype.splice
description: >
  Length values exceeding 2^53-1 are clamped to 2^53-1.
info: |
  1. ...
  2. Let len be ? ToLength(? Get(O, "length")).
  ...
  5. If the number of actual arguments is 0, then
    a. Let insertCount be 0.
    b. Let actualDeleteCount be 0.
  ...
  19. Perform ? Set(O, "length", len - actualDeleteCount + itemCount, true).
  ...
features: [exponentiation]
---*/

var arrayLike = {};

arrayLike.length = 2 ** 53 - 1;
Array.prototype.splice.call(arrayLike);
assert.sameValue(arrayLike.length, 2 ** 53 - 1, "Length is 2**53 - 1");

arrayLike.length = 2 ** 53;
Array.prototype.splice.call(arrayLike);
assert.sameValue(arrayLike.length, 2 ** 53 - 1, "Length is 2**53");

arrayLike.length = 2 ** 53 + 2;
Array.prototype.splice.call(arrayLike);
assert.sameValue(arrayLike.length, 2 ** 53 - 1, "Length is 2**53 + 2");

arrayLike.length = Infinity;
Array.prototype.splice.call(arrayLike);
assert.sameValue(arrayLike.length, 2 ** 53 - 1, "Length is Infinity");

// ===== test/built-ins/Array/prototype/splice/create-ctor-non-object.js =====
